<?php require_once "../includes/db.php";require_once "../includes/auth.php";require_admin();$items=$conn->query("SELECT b.*,p.name property_name FROM bookings b JOIN properties p ON p.id=b.property_id ORDER BY b.id DESC")->fetchAll(PDO::FETCH_ASSOC);$page_title="Booking";$root="../";include "../includes/header.php"; ?><section class="section"><div class="container"><div class="admin-menu"><a href="index.php">داشبۆرد</a></div><table><tr><th>ID</th><th>ناو</th><th>شوێن</th><th>Email</th><th>Phone</th><th>Check In</th><th>Check Out</th><th>Guests</th></tr><?php foreach($items as $b): ?><tr><td><?= $b["id"] ?></td><td><?= htmlspecialchars($b["full_name"]) ?></td><td><?= htmlspecialchars($b["property_name"]) ?></td><td><?= htmlspecialchars($b["email"]) ?></td><td><?= htmlspecialchars($b["phone"]) ?></td><td><?= $b["check_in"] ?></td><td><?= $b["check_out"] ?></td><td><?= $b["guests"] ?></td></tr><?php endforeach; ?></table></div></section><?php include "../includes/footer.php"; ?>